"""Command line interface: ``word2pdf in.docx [out.pdf]``."""
from __future__ import annotations

import argparse
import glob
import json
import os
import sys
import time

from . import __version__
from .api import Converter


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog='word2pdf',
        description='Convert .docx to PDF in pure Python - no Word, no '
                    'LibreOffice, no external binaries.')
    parser.add_argument('inputs', nargs='+', metavar='DOCX',
                        help='input .docx files (globs allowed)')
    parser.add_argument('-o', '--output', metavar='PDF',
                        help='output file (single input) or directory')
    parser.add_argument('-d', '--out-dir', metavar='DIR',
                        help='write the PDFs into this directory')
    parser.add_argument('--data', metavar='JSON',
                        help='JSON file (or inline JSON) of template values')
    parser.add_argument('--set', action='append', default=[], metavar='KEY=VALUE',
                        help='set one template value; repeatable')
    parser.add_argument('--no-jinja', action='store_true',
                        help='use the built-in template engine even if Jinja2 '
                             'is installed')
    parser.add_argument('--font-dir', action='append', default=[], metavar='DIR',
                        help='extra directory to search for fonts; repeatable')
    parser.add_argument('--default-font', default=None, metavar='NAME',
                        help='fallback font family (default: the document default)')
    parser.add_argument('--font-fallback', choices=('word', 'closest'),
                        default='word',
                        help="how to replace missing fonts: 'word' mimics Word "
                             "(document default), 'closest' matches width/style")
    parser.add_argument('--no-device-grid', action='store_true',
                        help='lay out in exact points instead of matching '
                             "Word's 600 dpi rounding")
    parser.add_argument('--no-compress', action='store_true',
                        help='write an uncompressed PDF')
    parser.add_argument('--image-quality', type=int, metavar='1-100',
                        help='re-encode photos as JPEG at this quality to '
                             'shrink the PDF (default: keep them untouched)')
    parser.add_argument('--image-max-dpi', type=int, metavar='DPI',
                        help='downsample images above this resolution')
    parser.add_argument('--title', help='PDF title metadata')
    parser.add_argument('--author', help='PDF author metadata')
    parser.add_argument('-q', '--quiet', action='store_true')
    parser.add_argument('-v', '--verbose', action='store_true',
                        help='report warnings and substituted fonts')
    parser.add_argument('--version', action='version',
                        version='Word2PDF %s' % __version__)
    return parser


def load_context(args) -> dict:
    context: dict = {}
    if args.data:
        raw = args.data
        if os.path.exists(raw):
            with open(raw, 'r', encoding='utf-8') as fh:
                context.update(json.load(fh))
        else:
            context.update(json.loads(raw))
    for item in args.set:
        key, _, value = item.partition('=')
        if not key:
            continue
        try:
            context[key.strip()] = json.loads(value)
        except ValueError:
            context[key.strip()] = value
    return context


def expand(patterns):
    files = []
    for pattern in patterns:
        matches = glob.glob(pattern) if any(ch in pattern for ch in '*?[') \
            else [pattern]
        if not matches:
            print('no such file: %s' % pattern, file=sys.stderr)
        files.extend(matches)
    return files


def target_for(source, args, many: bool):
    if args.out_dir:
        base = os.path.splitext(os.path.basename(source))[0] + '.pdf'
        return os.path.join(args.out_dir, base)
    if args.output and not many:
        if os.path.isdir(args.output):
            base = os.path.splitext(os.path.basename(source))[0] + '.pdf'
            return os.path.join(args.output, base)
        return args.output
    if args.output and many:
        base = os.path.splitext(os.path.basename(source))[0] + '.pdf'
        return os.path.join(args.output, base)
    return os.path.splitext(source)[0] + '.pdf'


def main(argv=None) -> int:
    args = build_parser().parse_args(argv)
    sources = expand(args.inputs)
    if not sources:
        return 1
    context = load_context(args) or None

    options = {'jinja': not args.no_jinja,
               'font_fallback': args.font_fallback,
               'compress': not args.no_compress}
    if args.no_device_grid:
        options['device_grid'] = 0
    if args.image_quality:
        options['image_quality'] = args.image_quality
    if args.image_max_dpi:
        options['image_max_dpi'] = args.image_max_dpi
    if args.title:
        options['title'] = args.title
    if args.author:
        options['author'] = args.author

    converter = Converter(font_dirs=args.font_dir or None,
                          default_font=args.default_font or 'Calibri',
                          **options)
    failures = 0
    for source in sources:
        target = target_for(source, args, len(sources) > 1)
        started = time.time()
        try:
            result = converter.convert(source, target, context=context)
        except Exception as exc:                       # pragma: no cover
            failures += 1
            print('%s: %s' % (source, exc), file=sys.stderr)
            continue
        if not args.quiet:
            print('%s -> %s (%d page%s, %.2fs)'
                  % (source, target, result.pages, '' if result.pages == 1 else 's',
                     time.time() - started))
        if args.verbose:
            for warning in result.warnings:
                print('  warning: %s' % warning, file=sys.stderr)
            if result.missing_fonts:
                print('  substituted fonts: %s' % ', '.join(result.missing_fonts),
                      file=sys.stderr)
    return 1 if failures else 0


if __name__ == '__main__':
    raise SystemExit(main())
